-- ---------------------------------------------------------
-- Absence records (last 12 months)
-- ---------------------------------------------------------
-- ---------------------------------------------------------
-- Attendance overrides (next couple of weeks)
-- ---------------------------------------------------------

-- ---------------------------------------------------------
-- Clock numbers: unique, randomised 5-digit numbers assigned
-- without replacement so no two employees in the company share
-- one.
-- ---------------------------------------------------------
with nums as (
  select (10000 + n)::text as num
  from generate_series(0, 89999) n
  order by random()
  limit (select count(*) from employees where company_id = (select id from companies where slug = 'prototype-factory'))
),
numbered_nums as (
  select num, row_number() over () as rn from nums
),
numbered_emps as (
  select id, row_number() over (order by random()) as rn
  from employees where company_id = (select id from companies where slug = 'prototype-factory')
)
update employees e set clock_number = nn.num
from numbered_emps ne join numbered_nums nn on nn.rn = ne.rn
where e.id = ne.id;
