insert into sops (id, company_id, department_id, code, title, version, owner, summary, steps, last_reviewed, review_due) values
  ('f55bfe83-b1c1-5e20-9492-a3301af83558', '28bf97dd-52f2-5477-992b-ce314072a8fb', '662d00c3-013a-5a35-98a2-939cf4b3364f', 'SOP-001', 'Site Health & Safety Induction Procedure', 'v3.0', 'H&S Manager', 'The standard induction every person on site must complete before working unsupervised, covering site rules, PPE and incident reporting.', ARRAY['Verify the individual''s identity and right-to-work documentation before induction begins.','Issue and fit-check required PPE for the areas they will work in.','Walk the site covering fire exits, assembly points, first aid points and the accident reporting process.','Cover site-specific hazards: vehicle movements, moving machinery, chemical storage and restricted areas.','Confirm understanding with a short verbal check and have the individual sign the induction record.','Issue site access/clock credentials only once induction is signed off.'], '2026-06-12', '2027-06-12'),
  ('95597eea-c734-548b-9029-a1ffea9d8d17', '28bf97dd-52f2-5477-992b-ce314072a8fb', '662d00c3-013a-5a35-98a2-939cf4b3364f', 'SOP-002', 'Manual Handling Procedure', 'v2.1', 'H&S Manager', 'Safe technique for lifting, carrying and moving materials by hand, to prevent musculoskeletal injury.', ARRAY['Assess the load: weight, shape, and whether it can be broken down or handled mechanically instead.','Plan the route, removing obstructions and confirming the destination is clear before lifting.','Adopt a stable stance, bend the knees not the back, and keep the load close to the body.','Lift smoothly without twisting; turn the feet instead of twisting the spine.','Use team lifts or mechanical aids for loads exceeding individual safe-lifting limits.','Report any strain or discomfort immediately rather than continuing to work through it.'], '2026-03-12', '2027-03-12'),
  ('5a52657e-b887-5f1c-82ef-20e95896fb42', '28bf97dd-52f2-5477-992b-ce314072a8fb', '662d00c3-013a-5a35-98a2-939cf4b3364f', 'SOP-003', 'Fire Safety & Emergency Evacuation Procedure', 'v2.0', 'H&S Manager', 'Actions to take on discovering a fire or hearing the alarm, and the evacuation route and muster process for the site.', ARRAY['On discovering a fire, raise the alarm immediately using the nearest call point.','Only attempt to tackle a small, contained fire if trained and it is safe to do so.','Evacuate via the nearest marked fire exit — do not use lifts.','Proceed directly to the designated assembly point without stopping to collect belongings.','Report to your assembly point marshal so headcount can be taken.','Do not re-enter the building until the all-clear is given by the fire marshal or emergency services.'], '2025-12-12', '2026-12-12'),
  ('f2bbb3a9-f935-5ec9-846f-0374ea256205', '28bf97dd-52f2-5477-992b-ce314072a8fb', '4f20e809-56cf-535e-bd4f-b3e61aac8629', 'SOP-004', 'Lockout / Tagout (LOTO) Procedure', 'v3.2', 'Engineering Manager', 'Isolating machinery safely before maintenance, cleaning or fault-clearing work, to prevent unexpected start-up.', ARRAY['Identify all energy sources for the equipment (electrical, pneumatic, hydraulic, stored energy).','Notify affected operators that the equipment is being isolated before work begins.','Isolate each energy source and apply a personal lock and tag to the isolation point.','Verify isolation by attempting to start the equipment using normal controls.','Carry out the maintenance or fault-clearing work within the isolated boundary only.','Remove locks and tags only once all personnel are clear and it is confirmed safe to re-energise.'], '2026-07-12', '2027-07-12'),
  ('12d8bed8-5bb2-579c-987b-92775734bc75', '28bf97dd-52f2-5477-992b-ce314072a8fb', 'd24069f1-e191-5396-9d14-a2c765149e2c', 'SOP-005', 'Food Safety & Hygiene (HACCP) Procedure', 'v4.1', 'Quality Manager', 'Hygiene, contamination control and HACCP critical control point checks required to maintain product food safety.', ARRAY['Complete hand-washing and hygiene checks at every designated control point.','Verify protective clothing, hairnets and jewellery policy before entering production areas.','Check critical control points (temperature, metal detection, visual inspection) at the required frequency.','Record all CCP checks on the quality system at the time they are performed, not retrospectively.','Escalate any CCP deviation immediately and hold affected product pending investigation.','Complete allergen changeover verification before running a different allergen profile on the same line.'], '2026-05-12', '2027-05-12'),
  ('2c71f39f-848b-56fe-bcd1-d6ce1c6dce85', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-006', 'Machine Operation — Line A', 'v1.4', 'Production Manager', 'Safe start-up, running and shutdown of Line A production equipment to specification.', ARRAY['Carry out pre-start checks: guarding in place, emergency stops tested, area clear.','Start the line following the sequence on the control panel checklist.','Monitor output against the running specification, checking at the defined sample frequency.','Respond to alarms and stoppages following the fault-finding flowchart before calling for support.','Record output, downtime and waste on the shift production log.','Shut down the line following the reverse start-up sequence and leave the area in a clean, safe state.'], '2026-04-12', '2027-04-12'),
  ('8009c532-eb9f-537e-8e27-61d57dc6c4de', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-007', 'Machine Operation — Line B', 'v1.3', 'Production Manager', 'Safe start-up, running and shutdown of Line B production equipment to specification.', ARRAY['Carry out pre-start checks: guarding in place, emergency stops tested, area clear.','Start the line following the sequence on the control panel checklist.','Monitor output against the running specification, checking at the defined sample frequency.','Respond to alarms and stoppages following the fault-finding flowchart before calling for support.','Record output, downtime and waste on the shift production log.','Shut down the line following the reverse start-up sequence and leave the area in a clean, safe state.'], '2026-01-12', '2027-01-12'),
  ('8678249c-1d67-5b15-b29e-a2cde2e1cf7f', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-008', 'Changeover & Setup Procedure', 'v2.3', 'Process Manager', 'Standard work for changing a production line between products to the target changeover time.', ARRAY['Confirm the next product specification and pull required tooling/materials in advance (external setup).','Isolate the line per the LOTO procedure before adjusting guarding or tooling.','Remove and store the outgoing product''s tooling and changeover parts correctly labelled.','Fit and align the incoming product''s tooling to the setup sheet dimensions.','Run a first-off sample and submit for quality sign-off before resuming full production.','Log actual changeover time against target and flag any deviation for process review.'], '2026-08-12', '2027-08-12'),
  ('f891016b-8682-54b9-ad2f-6c90a62f0b47', '28bf97dd-52f2-5477-992b-ce314072a8fb', 'd24069f1-e191-5396-9d14-a2c765149e2c', 'SOP-009', 'Quality Inspection & Checks Procedure', 'v2.0', 'Quality Manager', 'In-process and final inspection checks, sampling frequency and non-conformance handling.', ARRAY['Follow the sampling plan for the product being run (frequency, sample size, test method).','Record all measurements and pass/fail results on the quality system at the time of inspection.','Apply hold procedures immediately to any non-conforming product and notify the Quality Supervisor.','Retain traceability samples as required by the product''s quality plan.','Carry out line clearance checks between product runs to prevent cross-contamination.','Escalate recurring or trending defects rather than treating each one in isolation.'], '2026-02-12', '2027-02-12'),
  ('b0f351b0-d637-57ca-925a-c45e26a753e4', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-010', 'Forklift Operation Procedure', 'v1.2', 'Production Manager', 'Safe operation of counterbalance forklifts on site, for licensed operators only.', ARRAY['Carry out pre-use checks: tyres, forks, hydraulics, horn and warning lights.','Confirm load weight is within the truck''s rated capacity before lifting.','Sound the horn at blind corners and pedestrian crossing points.','Keep forks low and tilted back when travelling, raising only to place or remove a load.','Never carry passengers or use the forks to lift personnel.','Report any fault or near-miss immediately and take the truck out of service if unsafe.'], '2025-11-12', '2026-11-12'),
  ('fcdedb99-1623-5fe3-a959-37e094757297', '28bf97dd-52f2-5477-992b-ce314072a8fb', '4f20e809-56cf-535e-bd4f-b3e61aac8629', 'SOP-011', 'Preventative Maintenance Procedure', 'v2.4', 'Engineering Manager', 'Execution of planned preventative maintenance tasks to the schedule and standard required to maintain asset reliability.', ARRAY['Review the PPM schedule and pull the relevant task sheet and spares before starting.','Isolate the equipment per the LOTO procedure before any intrusive work.','Complete each task sheet item in sequence, recording readings and condition findings.','Replace parts at their scheduled life rather than running to failure where the schedule specifies.','Function-test the equipment after reassembly before returning it to production.','Close out the PPM record and raise a follow-up work order for any defect found but not resolved.'], '2026-09-12', '2027-09-12'),
  ('03700e20-b7bb-5402-bbe9-c39659b5a5e7', '28bf97dd-52f2-5477-992b-ce314072a8fb', '58b4d258-1616-5de8-8933-43527570f923', 'SOP-012', 'Daily Performance Review Procedure', 'v1.0', 'Operations Manager', 'The daily structure for reviewing safety, quality, delivery and cost performance across the site and agreeing same-day corrective actions.', ARRAY['Gather safety, quality, delivery and cost data from each department ahead of the review.','Hold the daily review at the agreed time with all department managers present or represented.','Walk through each KPI against target, focusing on exceptions rather than re-reading every metric.','Agree a named owner and a same-day or next-day action for every red metric.','Record decisions and actions in the daily review log.','Follow up open actions from the previous day before introducing new ones.'], '2026-08-12', '2027-08-12'),
  ('db4cc4d5-5f0d-5dbd-a3e9-7136f70d96c6', '28bf97dd-52f2-5477-992b-ce314072a8fb', '58b4d258-1616-5de8-8933-43527570f923', 'SOP-013', 'Operational Escalation Procedure', 'v1.0', 'Site Director', 'The route and timescales for escalating an operational issue that a department cannot resolve on its own.', ARRAY['Attempt first-line resolution within the department before escalating.','Escalate to the Operations Manager where the issue affects safety, quality, or more than one department.','Escalate to the Site Director where the issue carries significant commercial, safety, or regulatory risk.','State the issue, impact, and what has already been tried when escalating — not just the symptom.','Agree an owner and a target resolution time at the point of escalation.','Close the loop by confirming resolution back to everyone who was informed of the escalation.'], '2026-04-12', '2027-04-12'),
  ('a2d8a9b8-eb1b-5f86-a06a-7437c1fb7077', '28bf97dd-52f2-5477-992b-ce314072a8fb', '662d00c3-013a-5a35-98a2-939cf4b3364f', 'SOP-014', 'Risk Assessment Procedure', 'v2.0', 'H&S Manager', 'How a workplace risk assessment is carried out, reviewed and kept current for every task and area on site.', ARRAY['Identify the task or area being assessed and who carries out the work.','Identify hazards present and who could be harmed and how.','Evaluate the risk and identify existing and additional control measures required.','Record the assessment on the site risk assessment system with a review date.','Communicate relevant control measures to affected employees before work begins.','Review the assessment following any incident, process change, or at the scheduled review date.'], '2026-05-12', '2027-05-12'),
  ('3a1860be-9cb9-594e-afb1-ab40cee7ffa6', '28bf97dd-52f2-5477-992b-ce314072a8fb', '662d00c3-013a-5a35-98a2-939cf4b3364f', 'SOP-015', 'Accident Investigation Procedure', 'v2.1', 'H&S Manager', 'The process for investigating an accident or significant near-miss to establish root cause and prevent recurrence.', ARRAY['Secure the area and ensure the injured person receives appropriate first aid or medical attention.','Record initial facts while details are fresh: time, location, people involved, immediate cause.','Gather evidence: witness statements, photographs, equipment condition, relevant records.','Establish root cause using a structured method (e.g. 5-Why) rather than stopping at the immediate cause.','Agree corrective and preventative actions with named owners and target dates.','Report to the relevant authority where required and close out actions before considering the investigation complete.'], '2026-01-12', '2027-01-12'),
  ('a26ae11b-65cb-5ca5-9ed4-3e46fa6502d9', '28bf97dd-52f2-5477-992b-ce314072a8fb', 'd24069f1-e191-5396-9d14-a2c765149e2c', 'SOP-016', 'Non-Conformance Management Procedure', 'v1.3', 'Quality Manager', 'How a quality non-conformance is raised, contained, investigated and closed out, from detection through to corrective action.', ARRAY['Raise a non-conformance record as soon as an issue is detected, however minor it appears.','Contain the non-conforming product or process immediately to prevent further impact.','Assess the scope: how much product, how many batches, and whether customers are affected.','Investigate root cause and agree corrective action with a named owner and target date.','Verify the corrective action has been implemented and is effective before closing the record.','Review closed non-conformances periodically to identify recurring themes.'], '2026-06-12', '2027-06-12'),
  ('ca1360c8-f784-5ea9-84eb-c80128417544', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9a75ccaf-3913-53fc-8423-6aaa211e13a7', 'SOP-017', 'Cleaning & Sanitisation Procedure', 'v2.2', 'Hygiene Manager', 'The standard cleaning and sanitisation routine for production equipment, lines and facilities between and within shifts.', ARRAY['Follow the area-specific cleaning schedule for frequency and method.','Remove gross soil before applying cleaning chemicals, following correct dilution rates.','Apply sanitiser at the correct contact time before rinsing where required.','Carry out allergen-specific cleaning steps in full when changing between allergen profiles.','Visually inspect the area and equipment before sign-off.','Complete the clean-down record immediately after the clean, not at the end of shift.'], '2026-07-12', '2027-07-12'),
  ('1fd97aeb-ad9b-523d-bf40-d11b9c61026d', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9a75ccaf-3913-53fc-8423-6aaa211e13a7', 'SOP-018', 'Cleaning Verification Procedure', 'v1.1', 'Hygiene Manager', 'How a completed clean is independently verified before the line is released back to production.', ARRAY['Carry out a visual inspection of all contact and non-contact surfaces against the verification checklist.','Take swab or ATP samples at the defined verification points where required.','Compare results against the pass/fail threshold for that area.','Withhold line release and re-clean immediately on any verification failure.','Record verification results and sign-off on the hygiene system.','Escalate repeated verification failures in the same area to the Hygiene Manager for investigation.'], '2026-02-12', '2027-02-12'),
  ('8dc48a1f-2507-5607-9a2b-003e58025b12', '28bf97dd-52f2-5477-992b-ce314072a8fb', '8413c28d-8651-579f-88c1-f7cbc986a089', 'SOP-019', 'Employee Onboarding Procedure', 'v1.5', 'HR Manager', 'The steps taken from offer acceptance through to a new starter''s first weeks on site.', ARRAY['Complete right-to-work checks and issue the contract before the start date.','Prepare the new starter''s workstation, system access and PPE ahead of day one.','Deliver site induction and department-specific induction in the first week.','Assign a buddy or mentor and agree an initial training plan with the line manager.','Check in at 2 weeks, 1 month and end of probation to review progress.','Confirm successful completion of probation and update the employee record accordingly.'], '2026-03-12', '2027-03-12'),
  ('5f1ae959-8153-52c4-8283-cd85eff97e43', '28bf97dd-52f2-5477-992b-ce314072a8fb', '8413c28d-8651-579f-88c1-f7cbc986a089', 'SOP-020', 'Return-to-Work Interview Procedure', 'v1.2', 'HR Manager', 'How a return-to-work interview is conducted following any period of sickness absence, to support the employee and identify any underlying issues.', ARRAY['Hold the return-to-work interview on the employee''s first day back, without delay.','Confirm the reason for absence and whether it is now resolved.','Check whether any workplace adjustments or support are needed to aid full return to duties.','Review the employee''s absence record and flag any pattern for the manager''s attention.','Record the interview outcome on the HR system.','Agree any follow-up actions, including occupational health referral where appropriate.'], '2026-05-12', '2027-05-12'),
  ('61f64913-826d-5621-8072-e1e7f4a98fcb', '28bf97dd-52f2-5477-992b-ce314072a8fb', '112854be-8e78-5c14-ba6a-93be496ec3cb', 'SOP-021', 'New Product Development Process', 'v1.4', 'NPD Manager', 'The stage-gated process from product concept through to commercial launch.', ARRAY['Capture the product brief and commercial rationale at project initiation.','Develop and refine the formulation through bench-scale trials.','Validate the formulation against food safety, cost and specification requirements.','Run a scale-up trial on the production line with Quality and Operations present.','Gain sign-off at each stage gate before progressing to the next.','Hand over the finalised specification and standard work to Production for commercial launch.'], '2026-04-12', '2027-04-12'),
  ('d1d06845-1dd0-5887-abb0-ee1577d07ba2', '28bf97dd-52f2-5477-992b-ce314072a8fb', '112854be-8e78-5c14-ba6a-93be496ec3cb', 'SOP-022', 'Product Trial Management Procedure', 'v1.1', 'NPD Manager', 'How a product trial is planned and run on the production line with minimal disruption to the production plan.', ARRAY['Agree the trial scope, materials and line time required with the Production Manager in advance.','Brief the line team on what is being trialled and what to observe or record.','Run the trial following the pre-agreed protocol, capturing process data throughout.','Quarantine and clearly label all trial product pending review.','Review trial results against success criteria with NPD and Quality.','Document outcomes and next steps, whether that is scale-up, rework, or discontinuation.'], '2025-12-12', '2026-12-12'),
  ('507c366a-5484-5b9f-82d9-51f3616febfc', '28bf97dd-52f2-5477-992b-ce314072a8fb', '43396308-bb41-5d3e-a141-5a4b2715533b', 'SOP-023', 'Process Validation Procedure', 'v1.6', 'Process Manager', 'How a new or changed process is validated before being released to full production.', ARRAY['Define the validation criteria and acceptance limits before running the validation.','Run the process across the full range of normal operating conditions.','Record process parameters and output quality throughout the validation run.','Compare results against the pre-defined acceptance criteria.','Document the validation outcome and obtain sign-off from Process and Quality.','Update standard work and training materials to reflect the validated process.'], '2026-06-12', '2027-06-12'),
  ('93421287-641b-5d2a-8907-7fa6c62b7cdc', '28bf97dd-52f2-5477-992b-ce314072a8fb', '43396308-bb41-5d3e-a141-5a4b2715533b', 'SOP-024', 'Process Parameter Control Procedure', 'v1.3', 'Process Manager', 'How critical process parameters are monitored and controlled within their approved operating range during production.', ARRAY['Identify the critical parameters and their approved operating range for the process.','Monitor parameters at the defined frequency during the production run.','Respond immediately to any parameter trending out of range, before it breaches the limit.','Record any out-of-range event, the corrective action taken, and the outcome.','Escalate repeated excursions to the Process Engineer for root-cause investigation.','Review parameter trends periodically to identify drift before it becomes a failure.'], '2026-09-12', '2027-09-12'),
  ('f3aed890-3d7e-5e58-9402-36bfd468765f', '28bf97dd-52f2-5477-992b-ce314072a8fb', '676d2b6d-743c-5e4a-923e-156e305d3da4', 'SOP-025', 'Purchase Invoice Processing Procedure', 'v1.2', 'Finance Manager', 'How a supplier invoice is checked, approved and processed for payment.', ARRAY['Match the invoice to the purchase order and goods-received note.','Check pricing and quantities agree with the agreed terms.','Resolve any discrepancy with the supplier or requisitioner before approval.','Obtain approval from the budget holder in line with the delegated authority limits.','Process the invoice for payment within the agreed payment terms.','File the invoice and supporting documentation for audit purposes.'], '2026-03-12', '2027-03-12'),
  ('2365f05d-079a-532f-8c66-a38020c8a716', '28bf97dd-52f2-5477-992b-ce314072a8fb', '676d2b6d-743c-5e4a-923e-156e305d3da4', 'SOP-026', 'Budget Reporting Procedure', 'v1.1', 'Finance Manager', 'The monthly process for reporting site financial performance against budget.', ARRAY['Close the month''s transactions and complete accruals and reconciliations.','Prepare the management accounts and variance analysis against budget.','Review significant variances with the relevant department manager before publishing.','Present site financial performance to the Site Director and site leadership team.','Submit the finalised report to group finance within the reporting deadline.','Update the forecast for the remainder of the year based on year-to-date performance.'], '2026-07-12', '2027-07-12'),
  ('de8f106b-d0be-57ae-8aba-226cd2ea58f4', '28bf97dd-52f2-5477-992b-ce314072a8fb', '45cd9b85-cfae-5944-b37a-b06b395067fe', 'SOP-027', 'Customer Order Management Procedure', 'v1.3', 'Commercial Manager', 'How customer orders are received, confirmed and tracked through to delivery.', ARRAY['Log the customer order on receipt and confirm quantities, specification and delivery date.','Check the order against current stock and production capacity before confirming.','Raise any supply risk with Production and the customer as early as possible.','Track the order through production and dispatch, updating the customer on any change.','Confirm delivery with the customer and resolve any discrepancy promptly.','Record the completed order and update forecasting data for the account.'], '2026-04-12', '2027-04-12'),
  ('184e8598-0a74-5f64-9ce4-1aa58f76b10f', '28bf97dd-52f2-5477-992b-ce314072a8fb', '45cd9b85-cfae-5944-b37a-b06b395067fe', 'SOP-028', 'Customer Complaint Handling Procedure', 'v1.4', 'Commercial Manager', 'How a customer complaint is logged, investigated and responded to.', ARRAY['Log the complaint immediately with full details of the issue and the product/batch affected.','Acknowledge receipt with the customer within the agreed response time.','Investigate the complaint with Quality, including root cause where appropriate.','Agree the corrective action and any commercial resolution with the customer.','Respond formally to the customer with the outcome and any actions taken.','Record the complaint and resolution for trend analysis and review.'], '2026-01-12', '2027-01-12'),
  ('1f396b6e-c170-5b57-8cdd-e15c884e0de5', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-029', 'Production Line Start-Up Procedure', 'v2.0', 'Production Manager', 'The standard sequence for safely starting a production line at the beginning of a shift or following a stoppage.', ARRAY['Carry out pre-start safety checks: guarding, emergency stops, and area clear of personnel.','Confirm the correct product setup and specification are loaded for the run.','Start equipment in the defined sequence, following the control panel start-up checklist.','Run a first-off check and obtain quality sign-off before continuing to full rate.','Ramp up to full production rate, monitoring for any abnormal running conditions.','Record start-up time and any delay on the shift log.'], '2026-08-12', '2027-08-12'),
  ('4cbdbef5-c25b-5b46-8965-a20ad03a70a3', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-030', 'Production Shutdown Procedure', 'v1.5', 'Production Manager', 'The standard sequence for safely shutting down a production line at the end of a run or shift.', ARRAY['Complete the final production run and clear the line of in-process product.','Shut down equipment in the reverse of the start-up sequence.','Isolate equipment per the LOTO procedure if maintenance or cleaning will follow.','Record final output, downtime and waste figures for the shift.','Leave the area in a clean, safe condition for the next shift or clean-down team.','Complete shift handover notes for the incoming team or shift manager.'], '2026-02-12', '2027-02-12'),
  ('d3dbc789-4e7a-5e91-9ee5-1f96f745f3f5', '28bf97dd-52f2-5477-992b-ce314072a8fb', '9443aff0-236f-51de-bc55-5cd860c4d28d', 'SOP-031', 'Production Quality Checks Procedure', 'v1.2', 'Production Manager', 'The in-process quality checks Production itself carries out on the line, separate from formal Quality department inspection.', ARRAY['Carry out the defined visual and dimensional checks at the start of the run and at the set frequency.','Compare results against the running specification and flag any deviation immediately.','Quarantine any suspect product pending Quality review rather than continuing to run.','Record checks on the line quality log at the time they are performed.','Escalate any repeated or trending deviation to the Team Leader or Shift Manager.','Hand over open quality concerns clearly at shift change.'], '2026-05-12', '2027-05-12'),
  ('c8da1a65-b234-5e82-a564-c13de954cab2', '28bf97dd-52f2-5477-992b-ce314072a8fb', '4f20e809-56cf-535e-bd4f-b3e61aac8629', 'SOP-032', 'Equipment Breakdown Response Procedure', 'v2.1', 'Engineering Manager', 'How a production equipment breakdown is reported, responded to and resolved to minimise downtime.', ARRAY['Report the breakdown immediately to the Maintenance Team Lead with equipment and fault details.','Isolate the equipment per the LOTO procedure before any diagnostic or repair work begins.','Diagnose the fault and determine whether it can be first-line fixed or needs escalation.','Prioritise the repair against other open work based on safety and production impact.','Function-test the equipment before returning it to production.','Record the breakdown, root cause and resolution on the maintenance system for trend analysis.'], '2026-07-12', '2027-07-12');
