  ('72ed436a-11f0-57ca-92a8-c47cbe3d61aa', '28bf97dd-52f2-5477-992b-ce314072a8fb', 'e1f03da1-0241-52a3-9201-4d27de399ff4', 'd24069f1-e191-5396-9d14-a2c765149e2c', 'f47bc68e-a575-5de9-aa39-1a73b95fe559', 'cf4db6e3-f649-5bb6-a8af-8d96dfeb7e3f', 'PRO-0015', 'Callum', 'Fenton', 'callum.fenton@prototype-factory.demo', 'active', 42, '2026-01-05', '#406FB6', 'direct', 'hourly', '5207b75e-c017-5e68-a41c-ad179d1e18aa', 23, 18),
